API Gateway & Security.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_security, "API Gateway & Security") {
    Component(Perimeter_Defense_Filter, "Perimeter Defense Filter", "AWS WAF", "Protects the perimeter against common web exploits and OWASP Top-10 vulnerabilities.")
    Component(API_Gateway_Router, "API Gateway Router", "AWS API Gateway", "Routes client requests to backend ECS Fargate services and manages entry points.")
    Component(Authorizer, "Authorizer", "AWS Lambda Authorizer", "Performs JWT validation and RBAC enforcement for incoming requests.")
}

Rel(Perimeter_Defense_Filter, API_Gateway_Router, "Inspects and filters incoming HTTP/REST requests", "HTTP/REST")
Rel(API_Gateway_Router, Authorizer, "Invokes for token validation and access control", "AWS Lambda Invocation")

@enduml

Catalogue Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(Catalogue_Service, "Catalogue Service") {
    Component(Catalogue_API_Controller, "Catalogue API Controller", "Node.js (NestJS) or Go (Gin)", "Handles high-throughput, non-blocking I/O incoming requests from the API Gateway.")
    Component(Search_and_Query_Engine, "Search and Query Engine", "Amazon ElastiCache Redis, Amazon DynamoDB", "Serves low-latency keyword searches and fast catalogue read models.")
}

Rel(Catalogue_API_Controller, Search_and_Query_Engine, "Queries fast catalogue read models and serves low-latency searches", "Internal VPC Connection")
@enduml

Amazon Aurora PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon Aurora PostgreSQL container

Container_Boundary(amazon_aurora_postgresql, "Amazon Aurora PostgreSQL") {
    Component(aurora_serverless_v2_engine, "Aurora Serverless v2 Engine", "PostgreSQL 15 / AWS RDS", "Provides transactional data storage and automatically scales compute capacity for the online bookstore.")
    Component(aurora_distributed_storage, "Aurora Distributed Storage", "AWS Aurora Distributed Storage", "Handles 6-way replication across 3 Availability Zones ensuring high availability and durability.")
}

Rel(aurora_serverless_v2_engine, aurora_distributed_storage, "Replicates data securely across 3 AZs (6-way replication)", "Internal VPC connection")

@enduml

Amazon ElastiCache.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon ElastiCache container

Container_Boundary("Amazon ElastiCache", "Amazon ElastiCache") {
    Component("Cache Management Engine", "Cache Management Engine", "Redis OSS v7.0+", "In-memory cache engine for ultra-fast multi-currency exchange rate lookups and ephemeral session tokens.")
    Component("Cache Data Store", "Cache Data Store", "In-Memory Key-Value Store", "Stores session state, cart tokens, and frequently accessed localization data for low-latency retrieval.")
}

Rel("Cache Management Engine", "Cache Data Store", "Executes GET/SET commands over TCP/TLS [RESP]", "TCP/TLS [RESP]")

@enduml
